create extension if not exists pgcrypto;
create type public.investigation_status as enum ('draft','ready','analyzing','complete','archived');
create type public.analysis_status as enum ('queued','processing','complete','failed');
create type public.review_status as enum ('open','reviewing','resolved','dismissed','investigating');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default 'Investigator', role text not null default 'Investigator', workspace text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.investigations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, name text not null, description text not null default '', incident_date date, status public.investigation_status not null default 'draft', confidence integer not null default 0 check (confidence between 0 and 100), timeline_confidence integer not null default 0 check (timeline_confidence between 0 and 100), requires_review integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.evidence (id uuid primary key default gen_random_uuid(), investigation_id uuid not null references public.investigations(id) on delete cascade, uploaded_by uuid not null references public.profiles(id), filename text not null, mime_type text not null, size_bytes bigint not null, storage_path text not null unique, status text not null default 'processing', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.analysis_runs (id uuid primary key default gen_random_uuid(), investigation_id uuid not null references public.investigations(id) on delete cascade, status public.analysis_status not null default 'queued', stage text not null default '01 Ingesting evidence', progress integer not null default 0 check (progress between 0 and 100), started_at timestamptz, completed_at timestamptz, error_message text, created_at timestamptz not null default now());
create table public.evidence_extractions (id uuid primary key default gen_random_uuid(), evidence_id uuid not null references public.evidence(id) on delete cascade, extracted_text text, observations jsonb not null default '[]', relevant_time text, confidence text not null default 'medium', created_at timestamptz not null default now());
create table public.timeline_events (id uuid primary key default gen_random_uuid(), investigation_id uuid not null references public.investigations(id) on delete cascade, event_time timestamptz, title text not null, description text not null default '', confidence text not null default 'medium', basis text not null default 'uncertain', evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table public.contradictions (id uuid primary key default gen_random_uuid(), investigation_id uuid not null references public.investigations(id) on delete cascade, title text not null, description text not null default '', severity text not null default 'medium', confidence text not null default 'medium', evidence_ids uuid[] not null default '{}', resolution_needed text, review_status public.review_status not null default 'open', created_at timestamptz not null default now());
create table public.unknowns (id uuid primary key default gen_random_uuid(), investigation_id uuid not null references public.investigations(id) on delete cascade, title text not null, description text not null default '', time_window text, recommended_evidence text[] not null default '{}', severity text not null default 'medium', review_status public.review_status not null default 'open', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, investigation_id uuid references public.investigations(id) on delete cascade, title text not null, body text not null, kind text not null default 'info', read boolean not null default false, created_at timestamptz not null default now());
create table public.audit_log (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), investigation_id uuid references public.investigations(id) on delete set null, action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,full_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name','Investigator')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace view public.investigation_summary with (security_invoker=true) as select i.*, count(distinct e.id)::int evidence_count, count(distinct te.id)::int event_count, count(distinct c.id)::int contradiction_count, count(distinct u.id)::int unknown_count from public.investigations i left join public.evidence e on e.investigation_id=i.id left join public.timeline_events te on te.investigation_id=i.id left join public.contradictions c on c.investigation_id=i.id left join public.unknowns u on u.investigation_id=i.id group by i.id;
create or replace function public.is_owner(inv uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.investigations where id=inv and owner_id=auth.uid()); $$;
alter table public.profiles enable row level security; alter table public.investigations enable row level security; alter table public.evidence enable row level security; alter table public.analysis_runs enable row level security; alter table public.evidence_extractions enable row level security; alter table public.timeline_events enable row level security; alter table public.contradictions enable row level security; alter table public.unknowns enable row level security; alter table public.notifications enable row level security; alter table public.audit_log enable row level security;
create policy "own profile" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own investigations" on public.investigations for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "investigation children" on public.evidence for all using (public.is_owner(investigation_id)) with check (public.is_owner(investigation_id));
create policy "investigation runs" on public.analysis_runs for all using (public.is_owner(investigation_id)) with check (public.is_owner(investigation_id));
create policy "extractions through evidence" on public.evidence_extractions for all using (exists(select 1 from evidence e where e.id=evidence_id and public.is_owner(e.investigation_id))) with check (exists(select 1 from evidence e where e.id=evidence_id and public.is_owner(e.investigation_id)));
create policy "timeline through investigation" on public.timeline_events for all using (public.is_owner(investigation_id)) with check (public.is_owner(investigation_id));
create policy "contradictions through investigation" on public.contradictions for all using (public.is_owner(investigation_id)) with check (public.is_owner(investigation_id));
create policy "unknowns through investigation" on public.unknowns for all using (public.is_owner(investigation_id)) with check (public.is_owner(investigation_id));
create policy "own notifications" on public.notifications for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own audit" on public.audit_log for select using (user_id=auth.uid());
insert into storage.buckets(id,name,public) values ('evidence','evidence',false) on conflict (id) do nothing;
create policy "evidence read own" on storage.objects for select to authenticated using (bucket_id='evidence' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "evidence upload own" on storage.objects for insert to authenticated with check (bucket_id='evidence' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "evidence delete own" on storage.objects for delete to authenticated using (bucket_id='evidence' and (storage.foldername(name))[1]=auth.uid()::text);
